import {renderStreakActivity} from './streak-activity.mjs?v=period43';
import {createVerseStudios} from './verse-studios.mjs?v=story2';
import {renderPersonalHome} from './personal-home.mjs?v=home-live1';
import {streakSummary,calendarWeek} from './streak.mjs?v=rhythm2';
import {passageArtwork} from './discover-model.mjs?v=artwork1';
// Native-build parity review. Local fixtures only: never connects to auth, billing or production.
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const load=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
export const reviewRoutes=[['read','Bible reader'],['chapters','Chapter picker'],['bookmarks','Bookmarks'],['insights','Passage insights'],['explain','Explain easier'],['deeper','Deeper study'],['original','Original language'],['related','Related verses'],['reflection','Reflection & notes'],['widget','Widget Studio'],['snapshot-studio','Snapshot Studio'],['share','Share verse'],['community','Community'],['discover','Discover'],['home','Home'],['saved','Library · Verses'],['notes','Library · Notes'],['studies','Library · Studies'],['studied','Library · Studied'],['plans','Reading plans'],['plan','Plan detail'],['devotional','Devotional detail'],['progress','Streak & progress'],['settings','Settings'],['account','Your account'],['signin','Sign in'],['subscription','Subscription'],['appearance','Appearance'],['app-icon','App icon'],['topics','On your heart'],['reading','Bible text & reminders'],['support','Contact & support'],['faq','Help & FAQs'],['privacy','Privacy policy'],['terms','Terms of use'],['refunds','Refunds & cancellation'],['credits','Credits & licenses'],['paywall','Plus paywall'],['offer','Decline offer'],['restore','Restore purchases'],['delete','Delete account'],['onboarding','Onboarding']];
export function createNativeReview(a){
 const key='her-crown-native-review-v1';let d={appIcon:'white',notes:{},studies:[],studied:[],bookmarks:[],chaptersRead:[],devotionalsRead:[],planProgress:{},translation:'kjv',fontSize:'default',red:false,appearance:'light',membership:'free',account:false,widget:'Psalm 23:1',...load(key,{})};
 let streakRange='week';let homeSection='Library';let homeNoteReturn=false;
 let lastMain='home';let route='',back='settings',section='Verses',scenario='loaded',returnRoute='',selected='ps23',tool='explain',bookPick='Genesis',bibles={},devotionals=[],searchQuery='',overlay='',pending=false;
 const root=document.querySelector('#app');const $=s=>document.querySelector(s);const state=()=>a.getState();const save=()=>{try{localStorage.setItem(key,JSON.stringify(d))}catch{a.toast('Storage unavailable; changes last for this visit.')}};
 const art=(name,size=88)=>`<img class="nr-art" src="illustration-pack/${name}.png" alt="" width="${size}" height="${size}">`;
 const button=(label,action,cls='secondary',extra='')=>`<button class="${cls}" data-nr="${action}" ${extra}>${label}</button>`;
 const row=(label,dest,sub='',ic='chevron')=>`<button class="nr-row" data-nr="${dest}"><span class="nr-row-symbol">${a.icon(ic)}</span><span><strong>${label}</strong>${sub?`<small>${esc(sub)}</small>`:''}</span>${a.icon('chevron')}</button>`;
 const head=(title,close='back')=>`<header class="nr-header"><button class="iconbtn" data-nr="${close}" aria-label="Back">${a.icon('back')}</button><h1>${title}</h1><button class="textbtn" data-nr="done">Done</button></header>`;
 const intro=(name,title,text)=>`<div class="nr-intro">${art(name)}<h2>${title}</h2><p>${text}</p></div>`;
 function v(id=selected){const p=a.findPassage(id);if(p)return p;return a.findPassage('ps23')}
 function quote(id=selected){const p=v(id);return `<div class="nr-quote"><h2>${esc(p.ref)}</h2><blockquote>${esc(textFor(p.ref)||p.text)}</blockquote><small>${{kjv:'King James Version',bsb:'Berean Standard Bible',web:'World English Bible'}[d.translation]}</small></div>`}
 const current=()=>{const r=a.getReader();return a.passageId(a.chapters[r.chapter]?.[r.index]?.[1]||'Psalm 23:1')};
 const canonical=id=>v(id).ref;
 const studioVerse=ref=>{const passage=a.findPassage(a.passageId(ref));return {reference:ref,text:textFor(ref)||passage?.text||'Verse text unavailable. Reopen this verse in the Bible reader.',translation:d.translation.toUpperCase()}};
 const studios=createVerseStudios({premium:()=>['active','trial','grace'].includes(d.membership),daily:()=>studioVerse(a.verses[0].ref),widgetSaved:payload=>{if(payload.source==='chosen')d.widget=payload.reference;d.widgetStudio={source:payload.source,design:payload.design};save();},closed:()=>{}});
 function snapshotStudio(){const verse=studioVerse(v().ref);$('#detail-dialog')?.close();overlay='';studios.openSnapshot(verse);}
 function widgetStudio(){const verse=studioVerse(d.widget||v().ref);$('#detail-dialog')?.close();overlay='';studios.openWidget(verse);}

 function textFor(ref){const m=ref.match(/^(.+) (\d+):(\d+)$/);if(!m)return '';const book=bibles[d.translation]?.books.find(b=>label(b.name)===m[1]);return book?.chapters[+m[2]-1]?.verses.find(x=>x.n===+m[3])?.t||''}
 const label=name=>name==='Psalms'?'Psalm':name;
 const fixtureNote=()=>Object.entries(d.notes).filter(([,t])=>t.trim());
 function shell(title,body){return `<section class="feed nr-full settings-page">${head(title)}<div class="nr-content">${body}</div><dialog id="detail-dialog" aria-labelledby="dialog-title"><div class="dialog-inner"></div></dialog></section>`}
 function navigate(next){if(['read','home','discover','community'].includes(a.getTab()))lastMain=a.getTab();route=next;overlay='';a.go(['settings','account','signin','subscription','appearance','app-icon','topics','reading','support','faq','privacy','terms','refunds','credits','delete'].includes(next)?'settings':next==='plans'?'plans':next==='saved'?'saved':'home')}
 function group(title,body){return `<h3 class="nr-group-title">${title}</h3><div class="nr-group">${body}</div>`}
 const profile=()=>({...{name:'Nate',bio:'Making a little room for faith, every day.',photo:'assets/quiet-meadow.png'},...load('bible-scroll-profile-v1',{})});
 function control(title,name,options){return `<label class="nr-control"><span>${title}</span><select data-pref="${name}">${options.map(([value,text])=>`<option value="${value}" ${String(name==='appearance'&&d.appearance!=='system'?state().theme:d[name])===value?'selected':''}>${text}</option>`).join('')}</select></label>`}
 function settings(){const p=profile();return shell('Settings',`<button class="nr-profile" data-nr="account"><img src="${esc(p.photo)}" alt="Profile"><span><h2>Hi, ${esc(p.name)}!</h2><small>${d.account?'Signed in · Preview account':'Reading as a guest'}</small></span>${a.icon('chevron')}</button><div class="nr-membership">${art('butterfly',76)}<div><h2>A little space, just for you.</h2><p>${!['active','trial','grace'].includes(d.membership)?'Explore Her Crown Plus.':`Her Crown Plus · ${esc(d.membership)} preview`}</p>${button('View membership '+a.icon('arrow'),'subscription','textbtn')}</div></div>${group('Account & reading',row('Your account','account',d.account?'Signed in with Apple':'Guest · keep your reading safe','settings')+row('Bookmarks','bookmarks',d.bookmarks.length+' reading places','bookmark')+row('Saved passages','saved',state().saved.length+' passages','heart')+row('Subscription','subscription',!['active','trial','grace'].includes(d.membership)?'Free reading':'Her Crown Plus','bookmark')+control('Appearance','appearance',[['system','System'],['light','Light'],['dark','Dark']])+row('Widget Studio','widget-studio','Make your Home Screen your own','apps')+row('App icon','app-icon',iconChoices.find(x=>x.id===d.appIcon)?.label||'Cloud sky','apps')+row('On your heart','topics',state().topics.join(' · ')||'Choose topics','heart')+`<label class="nr-control">Reading pace<select id="routine">${a.questions[5].options.map(x=>`<option ${state().routine===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="nr-control">Daily reminder<input type="checkbox" data-pref="reminders" ${d.reminders?'checked':''}></label>${d.reminders?`<label class="nr-control">Reminder time<input type="time" data-pref="reminderTime" value="${d.reminderTime||'08:00'}"></label><p class="nr-muted">${scenario==='denied'?'Turn on notifications for Her Crown in iPhone Settings.':'One gentle reminder a day, at the time you choose. Simulated in this preview.'}</p>`:''}`)}${group('Bible text',control('Translation','translation',[['kjv','King James Version'],['bsb','Berean Standard Bible'],['web','World English Bible']])+control('Font size','fontSize',[['small','Small'],['default','Default'],['large','Large'],['largest','Largest']])+`<label class="nr-control">Words of Jesus in red<input data-pref="red" type="checkbox" ${d.red?'checked':''}></label>`)}${group('Here for you',row('Contact & Support','support','Questions, ideas or a little help','message')+row('Help & FAQs','faq','Let’s work it out together','info'))}${group('About & legal',['privacy','terms','refunds','credits'].map(x=>row({privacy:'Privacy Policy',terms:'Terms of Use',refunds:'Refunds & Cancellation',credits:'Credits & Licenses'}[x],x,'','document')).join(''))}<div class="nr-signoff">${art('olive',48)}<p>Rooted in Scripture. Made for real life.</p><small>Her Crown · Native-build UI review</small></div>`)}
 const iconChoices=[{id:'white',label:'Pure white'},{id:'cloud',label:'Cloud sky'},{id:'sage',label:'Soft sage'},{id:'blue',label:'Powder blue'}];
 function appIcons(){const selected=iconChoices.some(x=>x.id===d.appIcon)?d.appIcon:'white';return shell('App icon',`<div class="nr-icon-intro"><h2>A little more you.</h2><p>Choose the Her Crown you’d like on your Home Screen.</p></div><div class="nr-app-icon-grid" aria-label="Choose an app icon">${iconChoices.map(x=>`<button data-nr="choose-app-icon" data-icon="${x.id}" aria-pressed="${selected===x.id}" aria-label="${x.label}${selected===x.id?', selected':''}"><span class="nr-icon-art"><img src="app-icons/${x.id}.png" alt="" width="88" height="88">${selected===x.id?`<span class="nr-icon-check" aria-hidden="true">${a.icon('check')}</span>`:''}</span><strong>${x.label}</strong></button>`).join('')}</div><p class="nr-icon-preview-note">Icon selection is saved in this preview. The iOS app will apply it to your Home Screen.</p>`)}
 function account(){const p=profile();return shell('Your account',`<form id="nr-account"><div class="nr-photo"><img id="nr-photo-preview" src="${esc(p.photo)}" alt="Profile photo"><label class="secondary">${a.icon('camera')} Choose photo<input type="file" accept="image/jpeg,image/png,image/webp" id="nr-photo" hidden></label>${button('Remove photo','remove-photo','textbtn')}</div><label class="nr-field">Name<input name="name" value="${esc(p.name)}" maxlength="60" autocomplete="given-name"></label><label class="nr-field">Bio<textarea name="bio" maxlength="300">${esc(p.bio)}</textarea></label><p class="nr-muted">Your photo and profile stay on this browser in the mockup.</p><button class="primary" type="submit">Save</button></form>${group('Sign in',row(d.account?'Signed in with Apple':'Sign in with Apple','signin','Keep your saves, notes and reading history safe','shield'))}<p class="nr-muted">${d.account?'Your reading is saved to this preview account.':'You’re reading as a guest. Create an account to keep your reading when you change phones.'}</p>${button('Delete account','delete','nr-destructive')}`)}
 function library(){let list='';const ids=section==='Verses'?state().saved:section==='Notes'?fixtureNote().map(([id])=>id):section==='Studies'?d.studies.map(x=>x.id):d.studied;const visible=scenario==='empty'?[]:[...new Set(ids)];if(scenario==='loading')list=loading('Loading your library…');else if(scenario==='error')list=error('Your library couldn’t load. Your reading is still on this device.','saved');else list=visible.length?visible.map(id=>{const p=v(id);return `<article class="nr-library-card"><div class="passage-library-heading">${art(passageArtwork(p),64)}<h3>${esc(p.ref)}</h3></div><blockquote>${esc(textFor(p.ref)||p.text)}</blockquote>${section==='Notes'?`<p class="nr-note-excerpt">${esc(d.notes[id])}</p>`:''}${section==='Studies'?'<small>Saved study · Commentary, separate from Scripture</small>':''}<div class="nr-card-actions">${button(section==='Notes'?'Edit note':section==='Studies'?'Open study':'Read & reflect','library-open','textbtn',`data-id="${esc(id)}"`)}${button('Remove','library-remove','textbtn',`data-id="${esc(id)}"`)}</div></article>`}).join(''):empty('bookmark',section==='Notes'?'A home for your thoughts.':section==='Studies'?'Keep a little understanding close.':section==='Studied'?'Your study journey starts here.':'Words to keep close.',section==='Notes'?'Notes you write beside a verse will appear here.':section==='Studied'?'Mark a Discover passage as studied to collect it here.':'Save a passage or study to return to it.','Open the Bible','read');return shell('Saved passages',`<p class="nr-muted">Words to keep close.</p><div class="nr-segments" aria-label="Library sections">${['Verses','Notes','Studies','Studied'].map(x=>`<button data-nr="library-section" data-section="${x}" aria-pressed="${section===x}">${x} <small>${x==='Verses'?state().saved.length:x==='Notes'?fixtureNote().length:x==='Studies'?d.studies.length:d.studied.length}</small></button>`).join('')}</div>${list}`)}
 function empty(asset,title,body,cta,action){return `<div class="nr-empty">${art(asset,136)}<h2>${title}</h2><p>${body}</p>${cta?button(cta,action):''}</div>`}
 const loading=message=>`<div class="nr-loading" role="status"><span></span>${message}</div>`;
 const error=(message,retry)=>`<div class="nr-empty">${art('anchor',100)}<h2>A little interruption.</h2><p>${message}</p>${button('Try again',retry)}</div>`;
 function plans(){return shell('Reading Plans',intro('journal','A place to begin.','Read at your own pace, one passage at a time.')+a.plans.map(p=>`<button class="nr-plan-card" data-nr="plan" data-plan="${p.id}">${art(p.id==='quiet'?'sunrise':p.id==='peace'?'dove':'anchor',96)}<span><h2>${p.title}</h2><small>${p.refs.length} passages · about 2 min each</small><p>${p.sub}</p><strong>${state().plan===p.id?'Continue reading':'Explore plan'} →</strong></span></button>`).join(''))}
 function plan(){const p=a.plans.find(x=>x.id===(state().plan||'peace'))||a.plans[0],done=d.planProgress[p.id]||[];return intro('journal',p.title,p.sub)+`<p class="nr-muted">${done.length} of ${p.refs.length} passages · Read at your own pace</p><div class="nr-group">${p.refs.map((id,i)=>`<button class="nr-row" data-nr="plan-read" data-id="${id}"><span class="nr-step">${done.includes(id)?a.icon('check'):i+1}</span><span><strong>${esc(v(id).ref)}</strong><small>${done.includes(id)?'Completed':'A moment in the Word'}</small></span>${a.icon('chevron')}</button>`).join('')}</div>${button(!['active','trial','grace'].includes(d.membership)?'Start with Plus':done.length===p.refs.length?'Read again':'Continue plan',!['active','trial','grace'].includes(d.membership)?'paywall':'plan-next','primary')}<p class="nr-muted">Reading plans are part of Plus. Reading the Bible stays free.</p>`}
 function preferences(){return shell('Bible text & reminders',intro('open-book','Make yourself at home.','A reading experience that feels right for you.')+group('Bible text',control('Translation','translation',[['kjv','King James Version'],['bsb','Berean Standard Bible'],['web','World English Bible']])+control('Font size','fontSize',[['small','Small'],['default','Default'],['large','Large'],['largest','Largest']])+`<label class="nr-control">Words of Jesus in red<input data-pref="red" type="checkbox" ${d.red?'checked':''}></label>`)+group('Your daily pause',`<label class="nr-control">Reading pace<select id="routine">${a.questions[5].options.map(x=>`<option ${state().routine===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="nr-control">Daily reminder<input type="checkbox" data-pref="reminders" ${d.reminders?'checked':''}></label>${d.reminders?`<label class="nr-control">Reminder time<input type="time" data-pref="reminderTime" value="${d.reminderTime||'08:00'}"></label><p class="nr-muted">${scenario==='denied'?'Notifications are off. Turn them on in iPhone Settings to receive reminders.':'Notification timing is simulated in this browser preview.'}</p>`:''}`))}
 function appearance(){return shell('Appearance',intro('sunrise','Daylight or stillness.','Choose the appearance that feels right.')+control('Appearance','appearance',[['system','System'],['light','Light'],['dark','Dark']]))}
 function topics(){return shell('On your heart',intro('cosmos','What’s on your heart?','Choose the themes you’d like to make space for.')+`<div class="nr-choice-list">${a.questions[4].options.map(x=>`<button data-nr="topic" data-topic="${x}" aria-pressed="${state().topics.includes(x)}">${a.icon(state().topics.includes(x)?'check':'heart')} ${x}</button>`).join('')}</div>${button('Save','settings','primary')}`)}
 function subscription(){const premium=['active','trial','grace'].includes(d.membership);return shell('Subscription',intro('butterfly','Your reading, your way.','Enjoy free reading, or explore a little more with Plus.')+group('Current plan',`<div class="nr-inset"><h2>${premium?'Her Crown Plus':'Free reading'}</h2><p>${premium?`${esc(d.membership)} membership · simulated entitlement`:'Reading the Bible is always free. Plus adds reading plans and every study tool.'}</p>${d.membership==='trial'?'<p class="nr-banner">Your trial ends in 2 days. No charge is made in this preview.</p>':''}${button(premium?'Manage subscription':'Explore Her Crown Plus',premium?'manage-subscription':'paywall','primary')}</div>`)+group('Purchases',row('Restore Purchases','restore','','refresh')+row('Manage subscription','manage-subscription','','bookmark'))+'<p class="nr-muted">Subscriptions are billed and managed by Apple. Cancel at least 24 hours before your trial or period ends to avoid the next charge.</p>')}
 function legal(page){const titles={privacy:'Privacy Policy',terms:'Terms of Use',refunds:'Refunds & Cancellation',credits:'Credits & Licenses',faq:'Help & FAQs'};return shell(titles[page],`<div class="nr-document">${page==='faq'?['Is Bible reading free?','Can I read offline?','Where are my notes?','How do I cancel Plus?'].map((q,i)=>`<details><summary>${q}</summary><p>${['Yes. Scripture reading, saving and your streak remain available without Plus.','KJV, BSB and WEB are bundled in the native build. Online services such as study tools require a connection.','Open Saved passages, then choose Notes. Your thoughts are kept beside each verse.','Manage your subscription in iPhone Settings. Deleting your account does not stop Apple billing.'][i]}</p></details>`).join(''):`<p class="nr-banner">Build-kit text · Review copy, not legal advice.</p><div id="nr-legal-body">${loading('Opening document…')}</div>`}</div>`)}
 function support(){return shell('Contact & Support',intro('community','We’re here to help.','Questions, ideas or a little help with your reading.')+`<form id="nr-support"><label class="nr-field">Topic<select name="topic"><option>General question</option><option>Subscription</option><option>Something isn’t working</option><option>Study content</option></select></label><label class="nr-field">Your email<input type="email" name="email" placeholder="you@example.com" required></label><label class="nr-field">Message<textarea name="message" rows="6" placeholder="How can we help?" required></textarea></label><p class="nr-muted">Preview only. No message will be sent.</p><button type="submit" class="primary">Preview message</button></form>`)}
 function signin(){return shell('Save your account',intro('shield'==='x'?'anchor':'intention-heart','Keep your reading close.','Your saves, notes and reading history can follow you to a new phone.')+button('Continue with Apple','apple-signin','primary')+`<p class="nr-muted">Apple sign-in is simulated. No credentials are requested.</p>`+button('Continue as a guest','account','textbtn'))}
 function deleteView(){return shell('Delete account',intro('anchor','Before you go.','Deleting your account removes your profile, photo, saves, notes and reading history.')+`<p class="nr-banner">Deleting an account does not cancel an Apple subscription. This mockup will only show the confirmation; it does not delete your saved data.</p>`+button('Delete account','confirm-delete','nr-destructive')+button('Keep my account','account','secondary'))}
 function personalHome(){const source=a.verses[0],p=profile(),active=a.plans.find(x=>x.id===state().plan),x=devotionals[0];const notes=(scenario==='empty'?[]:fixtureNote()).map(([id,note])=>{const passage=v(id);return {id,ref:passage.ref,text:textFor(passage.ref)||passage.text,note}});const savedPlaces=(scenario==='empty'?[]:d.bookmarks).map(id=>{const passage=v(id);return {id,ref:passage.ref,text:textFor(passage.ref)||passage.text,art:passageArtwork(passage)}});const status=scenario==='loading'?loading('Opening your reading…'):scenario==='error'?error('Your reading couldn’t load. Please try again.','retry-home'):'';return renderPersonalHome({profile:p,verse:{...source,text:textFor(source.ref)||source.text,translation:d.translation.toUpperCase(),saved:state().saved.includes(source.id)},section:homeSection,streak:streakSummary(a.getDays()).current,plan:active?{id:active.id,title:active.title,done:(d.planProgress[active.id]||[]).length,total:active.refs.length}:null,devotional:x?{title:x.title,minutes:x.minutes||1,read:d.devotionalsRead.includes(x.id)}:null,notes,bookmarks:savedPlaces,icon:a.icon,navigation:a.navigation(),status,trialNotice:d.membership==='trial'?`<p class="nr-banner">Your free trial ends in 2 days. ${button('View membership','subscription','textbtn')}</p>`:''})}
 function homeSearch(){const bible=bibles[d.translation];if(!bible){show('Find a passage',`<p>Opening your Bible…</p>${button('Try again','home-search','secondary')}`,'home-search');return}const chosen=bible.books.find(b=>b.name===bookPick)||bible.books[0];bookPick=chosen.name;show('Find a passage',`<p class="nr-muted">Choose a passage to read and study.</p><label class="nr-field">Book<select id="nr-search-book">${bible.books.map(b=>`<option value="${esc(b.name)}" ${b.name===bookPick?'selected':''}>${esc(label(b.name))}</option>`).join('')}</select></label><div class="nr-split"><label class="nr-field">Chapter<select id="nr-search-chapter">${chosen.chapters.map((_,i)=>`<option>${i+1}</option>`).join('')}</select></label><label class="nr-field">Verse<select id="nr-search-verse">${chosen.chapters[0].verses.map(x=>`<option>${x.n}</option>`).join('')}</select></label></div>${button('Study this verse','search-study','primary')}`,'home-search')}
 function feed(tab){if(tab==='home')return personalHome();if(tab==='saved')return library();if(tab==='plans')return plans();if(tab==='settings'){const pages={account,signin,subscription,appearance,'app-icon':appIcons,topics,reading:preferences,support,delete:deleteView};return pages[route]?pages[route]():['privacy','terms','refunds','credits','faq'].includes(route)?legal(route):settings()}return null}
 function show(title,body,kind=''){overlay=kind;if(kind==='progress'){a.showDialog(`<div class="nr-sheet nr-streak"><header class="nr-rhythm-header"><h2 id="dialog-title" class="nr-rhythm-title">${title}</h2><button class="iconbtn" data-nr="done" aria-label="Close reading rhythm">${a.icon('close')}</button></header>${body}</div>`);return}a.showDialog(`<div class="nr-sheet ${kind==='progress'?'nr-streak':kind}"><header class="nr-sheet-header"><button class="textbtn" data-nr="sheet-back">${a.icon('back')} Back</button><button class="textbtn" data-nr="done">Done</button></header><h2 id="dialog-title" class="nr-sheet-title">${title}</h2>${body}</div>`)}
 function insights(id=current()){selected=id;show('Passage insights',`${art('open-book',68)}${quote()}<div class="nr-group">${[['explain','Explain easier','bulb'],['deeper','Deeper study','book'],['original','Original language','study'],['related','Related verses','link']].map(([id,title,ic])=>row(title,id,!['active','trial','grace'].includes(d.membership)?'Plus':'',ic)).join('')}${row(d.widget===canonical(selected)?'Widget verse set':'Set as your widget verse','widget','','apps')}</div>`,'insights')}
 function studyContent(){if(scenario==='loading')return loading('Preparing your study…');if(scenario==='offline'||scenario==='error')return error(scenario==='offline'?'Study tools need a connection. Your Bible still works offline.':'We couldn’t prepare this study. Please try again.','retry-study');if(!['active','trial','grace'].includes(d.membership))return intro('butterfly','Go deeper with Plus',`${titles[tool]} is part of Plus, along with reading plans and every study tool. Reading the Bible stays free.`)+button('See Her Crown Plus','paywall','primary');if(tool==='related'){const refs=dictionary[nativeRef()]?.related||[];return refs.length?`<p class="nr-muted">OpenBible.info cross-references · CC BY · Supplied build fixture</p>${refs.map(x=>{const id=refId(x.target),p=v(id);return row(p.ref,'related-open',textFor(p.ref)||p.text,'link').replace('data-nr="related-open"',`data-nr="related-open" data-id="${esc(id)}"`)}).join('')}`:empty('open-book','Read a little further.','Cross-references for this passage are not included in the offline review fixture.','','')}if(tool==='original')return `<p class="nr-banner">Original-language layout preview. The dictionary fixture below is sourced from the supplied build; it is not a fabricated translation.</p><div id="nr-word-list">${loading('Loading dictionary fixture…')}</div>`;return `<div class="nr-banner">Study commentary · separate from Scripture<br>Local design-review fixture, not a live AI response.</div><h3>${tool==='explain'?'Read it slowly':'Read in context'}</h3><p>${esc(v().reflection||'Read the surrounding verses to see this passage in its setting.')}</p><h3>A moment to consider</h3><p>What stands out to you in this passage? Take time to read it alongside the surrounding chapter.</p><details><summary>Sources & study notice</summary><p>In the native build, generated studies show citations and source licenses. This review fixture uses the supplied passage and reflection prompt without claiming a generated answer.</p></details><div class="nr-card-actions">${button(d.studies.some(x=>x.id===selected&&x.tool===tool)?'Saved':'Save study','save-study','textbtn')}${button('Note','reflection','textbtn')}${button('Copy','copy-study','textbtn')}</div>${button('Report a problem','report','textbtn')}`}
 const titles={explain:'Explain easier',deeper:'Deeper study',original:'Original language',related:'Related verses'};
 function study(which){tool=which;show(titles[tool],quote()+studyContent(),'study')}
 function reflection(){if(overlay!=='reflection')returnRoute=overlay;show('Reflection',`<img class="passage-study-art" src="illustration-pack/${passageArtwork(v())}.png" alt="" width="72" height="72">${quote()}<div class="reflection-block"><h3>A moment of reflection</h3><p>What stands out to you in this verse, and how might it shape your day?</p><small>Reflection prompt · not Scripture</small></div><label class="nr-field">Your notes<textarea id="nr-note" rows="7" placeholder="Write a thought, a prayer, a question…">${esc(d.notes[selected]||'')}</textarea></label><p class="nr-muted" id="nr-note-status">Notes save automatically on this browser.</p>`,'reflection')}
 function shareSheet(){show('Share verse',quote()+`<div class="nr-group">${row('Share verse text','copy-verse','','document')}${row('Snapshot Studio','snapshot-studio','Create an image of this verse','share')}${row('Set as widget verse','widget','','bookmark')}</div><p class="nr-muted">The native build opens the iOS share sheet. This preview keeps sharing local.</p>`,'share')}
 function widget(){d.widget=canonical(selected);save();show('Your widget verse',`<p class="nr-muted">Set for the native Home Screen widget. This is a visual preview.</p><div class="nr-widget">${art('cosmos',52)}<blockquote>${esc(textFor(d.widget)||v().text)}</blockquote><small>${esc(d.widget)}</small></div><p>In the iOS app, touch and hold your Home Screen, choose Add Widget, then Her Crown.</p>`,'widget')}
 function consecutiveWeeks(){const weeks=new Set(a.getDays().map(day=>{const dt=new Date(day+'T12:00:00');if(!Number.isFinite(+dt)||dt>new Date())return null;dt.setDate(dt.getDate()-((dt.getDay()+6)%7));return dt.toISOString().slice(0,10)}).filter(Boolean));const now=new Date();now.setDate(now.getDate()-((now.getDay()+6)%7));let count=0;for(let i=0;i<530;i++){const key=now.toISOString().slice(0,10);if(weeks.has(key))count++;else if(i>0)break;now.setDate(now.getDate()-7)}return count}
 function progress(){const days=a.getDays(),stats=streakSummary(days),week=calendarWeek(days),labels=['M','T','W','T','F','S','S'];show('Your reading rhythm',`<section class="nr-rhythm-summary" aria-label="Reading streak"><p class="nr-rhythm-count">${stats.current}</p><p class="nr-rhythm-caption">${stats.current===1?'Day':'Days'} of a little faithfulness</p>${renderStreakActivity(days,streakRange,`<div class="nr-rhythm-week" aria-label="This week, Monday to Sunday">${week.map((day,i)=>`<div class="nr-rhythm-day ${day.today?'is-today':''}" aria-label="${day.day}: ${day.read?'reading complete':day.future?'upcoming':'not read'}"><span>${labels[i]}</span><i class="${day.read?'is-read':''}">${day.read?'✓':'·'}</i></div>`).join('')}</div>`)}<p class="nr-rhythm-copy">${stats.readToday?'You made a little room for the Word today. Come back tomorrow and keep your rhythm growing.':'One quiet moment counts. Make a little room for the Word today.'}</p>${button(stats.readToday?'Read a little more':'Make time for today','streak-read','primary')}</section><details class="rhythm-more"><summary>More progress</summary><section class="nr-rhythm-details" aria-label="More reading progress"><div class="nr-rhythm-best"><span>Your longest streak</span><strong>${stats.best} ${stats.best===1?'day':'days'}</strong></div><div class="nr-progress"><h3>Through the Bible</h3><p>${d.chaptersRead.length} of 1,189 chapters</p><progress aria-label="Chapters read" max="1189" value="${d.chaptersRead.length}"></progress></div><h3>Your reading journal</h3>${[['Days read',days.length,'seedling'],['Weeks in a row',consecutiveWeeks(),'olive'],['Devotionals read',d.devotionalsRead.length,'journal'],['Verses studied',d.studied.length,'magnifier']].map(([title,count,asset])=>`<div class="nr-journal-row">${art(asset,36)}<span>${title}</span><strong>${count}</strong></div>`).join('')}<p class="nr-muted">One reading day counts once. Missing a full day starts a new run; your personal best stays.</p></section></details>`,'progress')}

 function devotional(){const x=devotionals[0];if(!x){show('Today’s devotional',loading('Opening devotional…'),'devotional');return}show(x.title,`<small>${x.minutes||1} min read · ${esc(x.tag)}</small>${art('journal',90)}${x.body.split('\n\n').map(t=>`<p>${esc(t)}</p>`).join('')}<p class="nr-muted">Reflection · separate from Scripture</p>${button('Read passage in context','devotional-context','primary')}`,'devotional');if(!d.devotionalsRead.includes(x.id)){d.devotionalsRead.push(x.id);save()}}
 function paywall(offer=false){if(!offer){overlay='original-paywall';document.querySelector('#detail-dialog')?.close();a.originalPaywall();return}pending=false;show('Her Crown Plus',intro('open-book','A little more room to grow.','Reading plans and every study tool, made for your daily walk.')+`<div class="nr-plus-benefits">${[['journal','Read with a little guidance'],['magnifier','Explore deeper understanding'],['intention-heart','Make space for your faith']].map(([asset,title])=>`<div>${art(asset,40)}<span>${title}</span></div>`).join('')}</div><div class="nr-plan-options"><label><input type="radio" name="nr-product" value="annual" checked><span><strong>${offer?'A gentle invitation · $19.99':'Yearly · $29.99'}</strong><small>Billed once per year${offer?' · one-time offer':''}</small></span></label>${offer?'':`<label><input type="radio" name="nr-product" value="weekly"><span><strong>Weekly · $2.99</strong><small>Billed every week</small></span></label>`}</div>${button('Continue','purchase','primary')}<p class="nr-muted">USD design fixtures. Purchase and trial terms come from Apple in the real app. No charge will occur here.</p>${button('Continue with free reading',offer?'dismiss-paywall':'offer','textbtn')}${button('Restore Purchases','restore','textbtn')}`,'paywall')}
 function restore(){show('Restore Purchases',intro('bookmark','Bring your reading back.','Check your Apple account for an existing subscription.')+`<p class="nr-banner">Simulated restore · no Apple account is contacted.</p>${scenario==='loading'?loading('Checking purchases…'):scenario==='error'?error('We couldn’t check purchases. Please try again.','restore'):!['active','trial','grace'].includes(d.membership)?`<p>No active subscription was found in this preview.</p>${button('Explore Plus','paywall','primary')}`:`<p>Her Crown Plus is available in this simulated account.</p>${button('Done','done','primary')}`}`,'restore')}
 function bookmarks(){show('Bookmarks',d.bookmarks.length?d.bookmarks.map(id=>row(v(id).ref,'bookmark-read','Continue reading','bookmark').replace('data-nr="bookmark-read"',`data-nr="bookmark-read" data-id="${esc(id)}"`)).join(''):empty('bookmark','Your place is waiting.','Tap the bookmark control in the reader to keep your place.','',''),'bookmarks')}
 function chapterPicker(){const books=bibles[d.translation]?.books||[];show('Choose a chapter',`<label class="nr-field">Search books<input id="nr-book-search" placeholder="Search books…"></label><div id="nr-books">${books.map(b=>`<button class="nr-row" data-nr="book-grid" data-book="${esc(b.name)}"><strong>${esc(label(b.name))}</strong><small>${b.chapters.length} chapters</small>${a.icon('chevron')}</button>`).join('')}</div>`,'chapters')}
 function bookGrid(book){bookPick=book;const b=bibles[d.translation]?.books.find(x=>x.name===book);show(label(book),`<div class="nr-chapter-grid">${b.chapters.map((_,i)=>button(i+1,'choose-chapter','',`data-label="${esc(label(book))} ${i+1}"`)).join('')}</div>`,'chapter-grid')}
 function openVerse(id){const p=v(id),m=p.ref.match(/^(.+) (\d+):(\d+)$/);$('#detail-dialog')?.close();route='';if(m)a.openReader(m[1]+' '+m[2],+m[3]-1)}
 function applyBible(){const bible=bibles[d.translation];if(!bible)return;for(const k of Object.keys(a.chapters))delete a.chapters[k];for(const b of bible.books)b.chapters.forEach((c,i)=>a.chapters[`${label(b.name)} ${i+1}`]=c.verses.map(x=>[x.t,`${label(b.name)} ${i+1}:${x.n}`]));a.render()}
 async function translation(t){d.translation=t;save();if(!bibles[t]){a.toast('Opening offline translation…');bibles[t]=await fetch(`native-data/${t}.json`).then(r=>r.json())}applyBible()}
 let dictionary={};fetch('native-data/study.json').then(r=>r.json()).then(x=>dictionary=x);
 function nativeRef(id=selected){const ref=v(id).ref,m=ref.match(/^(.+) (\d+):(\d+)$/);if(!m)return '';const book=bibles[d.translation]?.books.find(b=>label(b.name)===m[1]);return book?`${book.id}.${m[2]}.${m[3]}`:''}
 function refId(ref){const [book,ch,n]=ref.split('.');const b=bibles[d.translation]?.books.find(b=>b.id===book);return b?a.passageId(`${label(b.name)} ${ch}:${parseInt(n)}`):''}
 function fillDictionary(){const el=$('#nr-word-list');if(!el)return;const x=dictionary[nativeRef()];el.innerHTML=x?`<p class="nr-muted">${x.language==='grc'?'Greek':'Hebrew'} · STEPBible · CC BY 4.0</p>${x.words.map((w,i)=>`<button class="nr-word" data-nr="word" data-word="${i}"><span lang="${x.language==='grc'?'el':'he'}">${esc(w.text)}</span><strong>${esc(w.transliteration)}</strong><small>${esc(w.gloss)} · ${esc(w.strong)}</small>${a.icon('chevron')}</button>`).join('')}`:empty('open-book','Keep exploring.','This offline review fixture includes Genesis 1, Psalm 23, John 3, Romans 8, Hebrews 1 and 1 Corinthians 13.','','')}
 const markdown=s=>s.split('\n\n').map(p=>p.startsWith('#')?`<h3>${esc(p.replace(/^#+\s*/,''))}</h3>`:`<p>${esc(p).replace(/\n/g,'<br>')}</p>`).join('');
 function mounted(tab){root.style.setProperty('--nr-verse-size',({small:26,default:30,large:35,largest:40}[d.fontSize]||30)+'px');root.classList.toggle('nr-large-type',d.fontSize==='largest');
  if(tab==='read'){
   const trans=$('#reader-translation');if(trans)trans.innerHTML=['kjv','bsb','web'].map(x=>`<option value="${x}" ${d.translation===x?'selected':''}>${x.toUpperCase()}</option>`).join('');
   const bookmark=$('[data-action="bookmark-current"]');if(bookmark){bookmark.setAttribute('aria-label','Bookmark current verse; hold to view bookmarks');bookmark.addEventListener('contextmenu',e=>{e.preventDefault();bookmarks()})}
   const picker=$('#reader-chapter');if(picker){const labelEl=picker.previousElementSibling;const b=document.createElement('button');b.className='pill-control';b.dataset.nr='chapters';b.setAttribute('aria-label','Choose a chapter');b.textContent=a.getReader().chapter+' ⌄';picker.replaceWith(b);if(labelEl?.tagName==='LABEL')labelEl.remove()}
   const pages=$('.reader-pages');if(pages){const last=pages.lastElementChild;if(last){last.querySelector('.reader-hint').innerHTML=button('Continue to next chapter ↓','next-chapter','textbtn')}pages.querySelectorAll('blockquote').forEach(block=>{if(block.textContent.length>350)block.classList.add('nr-long-verse')})}
   const currentChapter=a.getReader().chapter;const book=bibles[d.translation]?.books.find(b=>currentChapter.startsWith(label(b.name)+' '));const ch=+currentChapter.split(' ').pop();if(d.red&&book){const lines=book.chapters[ch-1]?.verses||[];root.querySelectorAll('.reader-verse blockquote').forEach((el,i)=>{if(lines[i]?.wj?.length){const text=lines[i].t;let pos=0,html='';for(const [start,length] of lines[i].wj){const end=start+length;html+=esc(text.slice(pos,start))+'<span class="nr-red-letter">'+esc(text.slice(start,end))+'</span>';pos=end}el.innerHTML=html+esc(text.slice(pos))}})}
  }
  if(tab==='home'){
   const daily=$('.daily-card blockquote');if(daily)daily.textContent=textFor(a.verses[0].ref)||a.verses[0].text;const badge=$('.daily-card .version-badge');if(badge)badge.textContent=d.translation.toUpperCase();
   const dev=$('.devotional-card');if(dev){const x=devotionals[0];dev.innerHTML=`<span class="overline">Today’s devotional</span>${art('journal',70)}<h2>${x?esc(x.title):'Make room<br>for <em>the Word.</em>'}</h2><p>${x?esc(x.tag)+' · '+x.minutes+' min read':'A moment of reflection.'}</p>${button('Read today’s devotional '+a.icon('chevron'),'devotional','inline-action')}`}
   const search=$('.search-card');if(search&&bibles[d.translation])search.innerHTML=`<h2>${art('magnifier',40)} Verse Search</h2><p>Choose a passage to read and reflect on.</p><label class="nr-field">Book<select id="nr-search-book">${bibles[d.translation].books.map(b=>`<option value="${esc(b.name)}" ${b.name===bookPick?'selected':''}>${esc(label(b.name))}</option>`).join('')}</select></label><div class="nr-split"><label class="nr-field">Chapter<select id="nr-search-chapter">${(bibles[d.translation].books.find(b=>b.name===bookPick)?.chapters||[]).map((_,i)=>`<option>${i+1}</option>`).join('')}</select></label><label class="nr-field">Verse<select id="nr-search-verse"><option>1</option></select></label></div>${button('Study this verse','search-study','primary')}`;
   if(d.membership==='trial')$('.home-stack')?.insertAdjacentHTML('afterbegin',`<div class="nr-banner">Your free trial ends in 2 days. ${button('View membership','subscription','textbtn')}</div>`)
   $('.library-note')?.remove();
  }
  if(tab==='discover'){
   const feature=$('.discover-feature');if(feature)feature.hidden=['loading','error','offline','empty'].includes(scenario);
   if(['loading','error','offline','empty'].includes(scenario)){const stack=$('.discovery-stack');if(stack)stack.innerHTML=scenario==='loading'?loading('Finding passages for you…'):scenario==='empty'?empty('olive','A little room for something new.','No passages match this selection. Try For you.','Reset filters','discover'):error(scenario==='offline'?'Discover needs a connection. Your Bible still works offline.':'Discover couldn’t load. Please try again.','retry-discover')}
   else root.querySelectorAll('.verse-card').forEach(card=>{const id=card.querySelector('[data-study]')?.dataset.study;if(!id)return;const verse=v(id);const q=card.querySelector('blockquote');if(q)q.textContent='“'+(textFor(verse.ref)||verse.text)+'”';const tr=card.querySelector('.verse-translation');if(tr)tr.textContent={kjv:'King James Version',bsb:'Berean Standard Bible',web:'World English Bible'}[d.translation];if(d.studied.includes(id)){card.remove();return}card.insertAdjacentHTML('beforeend',button('Mark as studied '+a.icon('check'),'mark-studied','nr-studied-button',`data-id="${esc(id)}"`))})
  }
  if(route&&['privacy','terms','refunds','credits'].includes(route)){const active=route;fetch(`native-data/${route}.md`).then(r=>r.text()).then(text=>{if(route===active&&$('#nr-legal-body'))$('#nr-legal-body').innerHTML=markdown(text)})}
  document.querySelector('.nr-sheet.study #nr-word-list')&&fillDictionary();
 }
 function handle(e){const b=e.target.closest('button');if(!b)return false;
  if(b.dataset.homeSection){homeSection=b.dataset.homeSection;scenario='loaded';a.render();return true}
  if(b.dataset.homeNote){selected=b.dataset.homeNote;homeNoteReturn=true;reflection();return true}
  if(b.dataset.homeOpen){openVerse(b.dataset.homeOpen);return true}
  if(b.dataset.homeRemoveNote){delete d.notes[b.dataset.homeRemoveNote];save();a.render();return true}
  if(b.dataset.homeRemoveBookmark){d.bookmarks=d.bookmarks.filter(id=>id!==b.dataset.homeRemoveBookmark);save();a.render();return true}
  if(b.dataset.share){selected=b.dataset.share;shareSheet();return true}if(b.dataset.insight){selected=b.dataset.insight;insights(selected);return true}if(b.dataset.study){selected=b.dataset.study;reflection();return true}
  if(b.dataset.tab){route='';if(b.dataset.tab==='settings'){navigate('settings');return true}if(b.dataset.tab==='saved'){section='Verses';navigate('saved');return true}}
  if(b.dataset.plan){state().plan=b.dataset.plan;a.persist();show('Reading plan',plan(),'plan');return true}
  if(b.dataset.nr==='streak-range'){if(['week','6'].includes(b.dataset.range)){streakRange=b.dataset.range;progress()}return true}if(b.dataset.action==='show-streak'){progress();return true}if(b.dataset.action==='mark-read'&&overlay==='progress'){a.markRead();a.render();progress();return true}if(b.dataset.action==='membership'){paywall();return true}if(b.dataset.action==='study-selected'){selected=$('#verse-search')?.value||'ps23';insights(selected);return true}
  if(b.dataset.action==='bookmark-current'){const id=current();d.bookmarks=d.bookmarks.includes(id)?d.bookmarks.filter(x=>x!==id):[...d.bookmarks,id];save();a.toast(d.bookmarks.includes(id)?'Verse bookmarked':'Bookmark removed');return true}
  if(b.dataset.action==='random'&&bibles[d.translation]){const books=bibles[d.translation].books,bk=books[Math.floor(Math.random()*books.length)],ch=Math.floor(Math.random()*bk.chapters.length);a.openReader(`${label(bk.name)} ${ch+1}`,Math.floor(Math.random()*bk.chapters[ch].verses.length));return true}
  const action=b.dataset.nr;if(!action)return false;
  if(['account','signin','subscription','appearance','app-icon','topics','reading','support','faq','privacy','terms','refunds','credits','delete','settings','plans','saved'].includes(action)){navigate(action);return true}
  switch(action){
   case 'choose-app-icon':if(iconChoices.some(x=>x.id===b.dataset.icon)){d.appIcon=b.dataset.icon;save();a.render();a.toast('App icon selected')}break;
   case 'home-search':homeSearch();break;
   case 'home-plan':if(state().plan)show('Reading plan',plan(),'plan');else navigate('plans');break;
   case 'retry-home':scenario='loaded';a.render();break;
   case 'read':route='';a.go('read');break;
   case 'discover':scenario='loaded';route='';a.go('discover');break;
   case 'back':if(route&&route!=='settings'){route='settings';a.render()}else{route='';a.go(lastMain)}break;
   case 'done':if($('#detail-dialog')?.open){const refreshHome=a.getTab()==='home';$('#detail-dialog').close();overlay='';homeNoteReturn=false;if(refreshHome)a.render()}else{route='';a.go(lastMain)}break;
   case 'sheet-back':if(overlay==='reflection'&&homeNoteReturn){$('#detail-dialog')?.close();overlay='';homeNoteReturn=false;a.render()}else if(overlay==='word')study('original');else if(overlay==='reflection'&&returnRoute==='study')study(tool);else if(overlay==='plan-reading')show('Reading plan',plan(),'plan');else if(['study','widget','reflection','share'].includes(overlay))insights();else if(overlay==='chapter-grid')chapterPicker();else $('#detail-dialog')?.close();break;
   case 'library-section':section=b.dataset.section;a.render();break;
   case 'library-open':selected=b.dataset.id;section==='Notes'?reflection():section==='Studies'?study(d.studies.find(x=>x.id===selected)?.tool||'explain'):insights(selected);break;
   case 'library-remove':{const id=b.dataset.id;if(section==='Verses'){state().saved=state().saved.filter(x=>x!==id);a.persist()}if(section==='Notes')delete d.notes[id];if(section==='Studies')d.studies=d.studies.filter(x=>x.id!==id);if(section==='Studied')d.studied=d.studied.filter(x=>x!==id);save();a.render();break}
   case 'explain':case 'deeper':case 'original':case 'related':study(action);fillDictionary();break;
   case 'retry-study':scenario='loaded';study(tool);fillDictionary();break;
   case 'retry-discover':scenario='loaded';a.render();break;
   case 'save-study':{const found=d.studies.some(x=>x.id===selected&&x.tool===tool);d.studies=found?d.studies.filter(x=>!(x.id===selected&&x.tool===tool)):[...d.studies,{id:selected,tool}];save();study(tool);a.toast(found?'Study removed':'Saved to Studies');break}
   case 'copy-study':navigator.clipboard?.writeText(`${titles[tool]} · ${v().ref}\n${v().text}\nStudy review fixture · separate from Scripture`).then(()=>a.toast('Study copied'));break;
   case 'reflection':reflection();break;
   case 'snapshot-studio':snapshotStudio();break;case 'widget-studio':widgetStudio();break;case 'share':shareSheet();break;case 'copy-verse':navigator.clipboard?.writeText(`${textFor(v().ref)||v().text} — ${v().ref} (${d.translation.toUpperCase()})`).then(()=>a.toast('Verse copied'));break;case 'widget':d.widget=canonical(selected);save();widgetStudio();break;
   case 'word':{const w=dictionary[nativeRef()]?.words[+b.dataset.word];if(w)show(w.transliteration,`<div class="nr-dictionary"><h2>${esc(w.text)}</h2><p>${esc(w.gloss)} · ${esc(w.strong)}</p><small>${esc(w.parsing)}</small><h3>Dictionary entry</h3><p>${esc(w.definition?.definition||'A full entry is not included in this offline fixture.')}</p><small>STEPBible · CC BY 4.0</small></div>`,'word');break}
   case 'report':show('Report a problem',`<p>What’s wrong with this study?</p><div class="nr-group">${['It’s inaccurate','It’s unclear','It’s offensive','Something else'].map(x=>row(x,'report-reason')).join('')}</div><p class="nr-muted">Reports stay local in this design preview.</p>`,'report');break;
   case 'report-reason':show('Thank you.',intro('olive','We’ll take a look.','Your report is recorded in this local preview. No report has been sent.')+button('Back to study','retry-study','primary'),'reported');break;
   case 'mark-studied':selected=b.dataset.id;show('Mark as studied?',`<p>This study will leave Discover and move to Saved → Studied, including any notes you’ve written.</p>${button('Mark as Studied','confirm-studied','primary')}${button('Cancel','done','secondary')}`,'confirm');break;
   case 'confirm-studied':d.studied=[...new Set([...d.studied,selected])];save();$('#detail-dialog').close();a.render();a.toast('Moved to Saved → Studied');break;
   case 'chapters':chapterPicker();break;
   case 'book-grid':bookGrid(b.dataset.book);break;
   case 'choose-chapter':$('#detail-dialog').close();route='';a.openReader(b.dataset.label);break;
   case 'next-chapter':{const names=Object.keys(a.chapters),chapter=a.getReader().chapter;d.chaptersRead=[...new Set([...d.chaptersRead,chapter])];save();a.markRead();const next=names[(names.indexOf(chapter)+1)%names.length];a.openReader(next);break}
   case 'bookmarks':bookmarks();break;
   case 'bookmark-read':case 'related-open':openVerse(b.dataset.id);break;
   case 'search-study':{const book=$('#nr-search-book').value,ch=$('#nr-search-chapter').value,n=$('#nr-search-verse').value;selected=a.passageId(`${label(book)} ${ch}:${n}`);insights(selected);break}
   case 'plan':state().plan=b.dataset.plan||state().plan||'peace';a.persist();show('Reading plan',plan(),'plan');break;
   case 'plan-read':if(!['active','trial','grace'].includes(d.membership)){paywall();break}selected=b.dataset.id;show('Today’s reading',quote()+button('Read chapter','plan-context','primary')+button('Mark passage complete','plan-complete','secondary'),'plan-reading');break;
   case 'plan-context':openVerse(selected);break;
   case 'plan-complete':{const id=state().plan||'peace';d.planProgress[id]=[...new Set([...(d.planProgress[id]||[]),selected])];save();a.markRead();show('Reading plan',plan(),'plan');break}
   case 'plan-next':{const p=a.plans.find(x=>x.id===(state().plan||'peace'));selected=p.refs.find(id=>!(d.planProgress[p.id]||[]).includes(id))||p.refs[0];show('Today’s reading',quote()+button('Mark passage complete','plan-complete','primary'),'plan-reading');break}
   case 'devotional':devotional();break;
   case 'devotional-context':{const ref=devotionals[0]?.ref;const id=refId(ref);if(id)openVerse(id);break}
   case 'progress':progress();break;
   case 'streak-read':overlay='';document.querySelector('#detail-dialog')?.close();a.go('read');break;
   case 'topic':{const t=b.dataset.topic;state().topics=state().topics.includes(t)?state().topics.filter(x=>x!==t):[...state().topics,t];a.persist();a.render();break}
   case 'apple-signin':if(scenario==='error'){show('Sign in with Apple',error('Sign-in couldn’t finish. Please try again.','signin'),'signin');break}d.account=true;save();navigate('account');a.toast('Preview account linked. Existing reading kept.');break;
   case 'remove-photo':$('#nr-photo-preview').src='illustration-pack/cosmos.png';$('#nr-photo-preview').dataset.draft='illustration-pack/cosmos.png';break;
   case 'confirm-delete':show('Delete your account?',`<p>This can’t be undone in the real app. This design preview keeps your data intact.</p>${button('Preview deletion result','deletion-result','nr-destructive')}${button('Cancel','done','secondary')}`,'delete');break;
   case 'deletion-result':show('Your account was deleted.',intro('seedling','A fresh beginning.','The real app returns to a new guest session. No data was removed from this preview.')+button('Return to account','account','primary'),'deleted');break;
   case 'paywall':paywall();break;
   case 'offer':paywall(true);break;
   case 'dismiss-paywall':$('#detail-dialog').close();overlay='';break;
   case 'purchase':{if(pending)break;pending=true;if(scenario==='error')show('Purchase couldn’t complete',error('No payment was made. Please try again.','paywall'),'purchase');else if(scenario==='pending')show('Awaiting approval',intro('hourglass','A little patience.','Apple is waiting for purchase approval. You can keep reading while it’s pending.')+button('Keep reading','done','primary'),'purchase');else if(scenario==='cancelled')show('Purchase cancelled','<p>You haven’t been charged.</p>'+button('Return to plans','paywall','primary'),'purchase');else show('Purchase preview',intro('butterfly','Your next chapter.','This is a mock confirmation. No Apple purchase will be made.')+button('Preview Plus access','grant-preview-plus','primary')+button('Keep free reading','dismiss-paywall','secondary'),'purchase');break}
   case 'grant-preview-plus':d.membership='active';save();$('#detail-dialog').close();a.toast('Plus preview enabled · no purchase');a.render();break;
   case 'restore':restore();break;
   case 'manage-subscription':show('Manage subscription','<p>On iOS, this opens Apple’s subscription management screen.</p><p class="nr-muted">This preview does not open billing settings or change a subscription.</p>'+button('Done','done','primary'),'manage');break;
   default:return false;
  }return true;
 }
 document.body.addEventListener('click',e=>{const purchase=e.target.closest('[data-member="preview"]');if(!purchase||!['pending','cancelled','error'].includes(scenario))return;e.preventDefault();e.stopImmediatePropagation();document.querySelector('#membership-dialog')?.close();if(scenario==='pending')show('Awaiting approval',intro('hourglass','A little patience.','Apple is waiting for purchase approval. You can keep reading while it’s pending.')+button('Keep reading','done','primary'),'purchase');else if(scenario==='cancelled')show('Purchase cancelled','<p>You haven’t been charged.</p>'+button('Back to plans','paywall','primary'),'purchase');else show('Purchase couldn’t complete',error('No payment was made. Please try again.','paywall'),'purchase');},true);
 root.addEventListener('click',e=>{if(handle(e)){e.preventDefault();e.stopImmediatePropagation()}},true);
 root.addEventListener('input',e=>{if(e.target.id==='nr-note'){d.notes[selected]=e.target.value;save();$('#nr-note-status').textContent='Saved on this browser.'}if(e.target.id==='nr-book-search')$('#nr-books').querySelectorAll('[data-book]').forEach(b=>b.hidden=!b.dataset.book.toLowerCase().includes(e.target.value.toLowerCase()))});
 root.addEventListener('change',async e=>{
  if(e.target.id==='reader-translation'){e.stopImmediatePropagation();await translation(e.target.value);return}
  const pref=e.target.dataset.pref;if(pref){d[pref]=e.target.type==='checkbox'?e.target.checked:e.target.value;save();if(pref==='translation')await translation(d.translation);else if(pref==='appearance'){state().theme=d.appearance==='system'?(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'):d.appearance;a.persist();a.render()}else a.render()}
  if(e.target.id==='nr-photo'){const file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>10*1024*1024){a.toast('Choose a JPG, PNG or WebP under 10 MB.');return}const reader=new FileReader();reader.onload=()=>{const img=$('#nr-photo-preview');if(img){img.src=reader.result;img.dataset.draft=reader.result}};reader.readAsDataURL(file)}
  if(e.target.id==='nr-search-book'){bookPick=e.target.value;const bk=bibles[d.translation].books.find(x=>x.name===bookPick);$('#nr-search-chapter').innerHTML=bk.chapters.map((_,i)=>`<option>${i+1}</option>`).join('');$('#nr-search-verse').innerHTML=bk.chapters[0].verses.map(x=>`<option>${x.n}</option>`).join('')}
  if(e.target.id==='nr-search-chapter'){const bk=bibles[d.translation].books.find(x=>x.name===bookPick);$('#nr-search-verse').innerHTML=bk.chapters[+e.target.value-1].verses.map(x=>`<option>${x.n}</option>`).join('')}
 },true);
 root.addEventListener('submit',e=>{if(e.target.id==='nr-account'){e.preventDefault();const fd=new FormData(e.target),p=profile();p.name=String(fd.get('name')).trim()||'Nate';p.bio=String(fd.get('bio'));p.photo=$('#nr-photo-preview').dataset.draft||p.photo;try{localStorage.setItem('bible-scroll-profile-v1',JSON.stringify(p));a.toast('Profile saved')}catch{a.toast('Photo is too large to store. Try a smaller photo.')}}if(e.target.id==='nr-support'){e.preventDefault();const fd=new FormData(e.target);show('Message preview',`<p class="nr-muted">No message has been sent.</p><h3>${esc(fd.get('topic'))}</h3><p>${esc(fd.get('email'))}</p><p>${esc(fd.get('message'))}</p>${button('Edit message','support','secondary')}`,'support')}});
 function review(r,which='loaded',membership){scenario=which;if(which==='example'){const id='ps23';state().saved=[...new Set([...state().saved,id])];d.notes[id]||='Design-review example: make a little space for rest today.';if(!d.studies.some(x=>x.id===id&&x.tool==='explain'))d.studies.push({id,tool:'explain'});d.studied=[...new Set([...d.studied,id])];a.persist();scenario='loaded';}if(membership)d.membership=membership;save();if(r==='onboarding'){window.dispatchEvent(new Event('bible-onboarding-restart'));return}state().completed=true;a.persist();if(['read','community','discover','home'].includes(r)){route='';a.go(r);return}if(['notes','studies','studied','saved'].includes(r)){section={notes:'Notes',studies:'Studies',studied:'Studied',saved:'Verses'}[r];navigate('saved');return}if(['settings','account','signin','subscription','appearance','app-icon','topics','reading','support','faq','privacy','terms','refunds','credits','delete','plans'].includes(r)){navigate(r);return}route='';a.go('read');selected=current();({chapters:chapterPicker,bookmarks,insights,reflection,widget:widgetStudio,'widget-studio':widgetStudio,'snapshot-studio':snapshotStudio,share:shareSheet,progress,plan:()=>show('Reading plan',plan(),'plan'),devotional,paywall:()=>paywall(),offer:()=>paywall(true),restore,...Object.fromEntries(Object.keys(titles).map(x=>[x,()=>{study(x);fillDictionary()}]))}[r]||insights)()}
 function toggleTheme(){const before=overlay;state().theme=state().theme==='dark'?'light':'dark';d.appearance=state().theme;save();a.persist();a.render();if(before==='study'){study(tool);fillDictionary()}else if(before==='insights')insights();else if(before==='reflection')reflection();else if(before==='widget')widget();else if(before==='progress')progress();else if(before==='paywall')paywall();else if(before==='devotional')devotional();}
 window.addEventListener('message',e=>{if(e.origin!==location.origin||e.data?.type!=='her-crown-review')return;review(e.data.route,e.data.scenario,e.data.membership)});
 // Restore verified scripture without making any network requests outside localhost.
 fetch(`native-data/${d.translation}.json`).then(r=>r.json()).then(x=>{bibles[d.translation]=x;applyBible()}).catch(()=>a.toast('Offline Bible bundle could not load. Existing sample still available.'));
 fetch('native-data/devotionals.json').then(r=>r.json()).then(x=>{devotionals=x;if(a.getTab()==='home')a.render()});
 return {feed,mounted,review,toggleTheme,openPaywall:paywall};
}
